-- Reference schema for the VerdantCare Django SQLite database.
-- The authoritative schema is generated by Django migrations.
CREATE TABLE store_doctor (id integer primary key autoincrement, name varchar(120) not null, specialty varchar(120) not null, bio text not null, experience_years integer not null, consultation_fee decimal not null, available bool not null, created_at datetime not null);
CREATE TABLE store_medicine (id integer primary key autoincrement, name varchar(160) not null, category varchar(100) not null, description text not null, price decimal not null, stock integer not null, featured bool not null, image_url varchar(200) not null, created_at datetime not null);
CREATE TABLE store_order (id integer primary key autoincrement, customer_id bigint not null references auth_user(id), total_amount decimal not null, status varchar(20) not null, shipping_address text not null, placed_at datetime not null);
CREATE TABLE store_appointment (id integer primary key autoincrement, customer_id bigint not null references auth_user(id), doctor_id bigint not null references store_doctor(id), appointment_date date not null, appointment_time time not null, reason text not null, status varchar(20) not null, created_at datetime not null);
CREATE TABLE store_review (id integer primary key autoincrement, medicine_id bigint not null references store_medicine(id), customer_id bigint not null references auth_user(id), rating integer not null, comment text not null, approved bool not null, created_at datetime not null, moderated_at datetime null, unique(medicine_id, customer_id));
CREATE TABLE store_notificationpreference (id integer primary key autoincrement, user_id bigint not null unique references auth_user(id), site_enabled bool not null, email_enabled bool not null, sms_enabled bool not null, phone_number varchar(30) not null);
CREATE TABLE store_notification (id integer primary key autoincrement, user_id bigint not null references auth_user(id), event varchar(40) not null, channel varchar(10) not null, title varchar(180) not null, message text not null, read bool not null, delivered bool not null, created_at datetime not null);
CREATE TABLE store_coupon (id integer primary key autoincrement, code varchar(40) unique not null, discount_type varchar(10) not null, discount_value decimal not null, valid_from datetime not null, valid_until datetime not null, min_order_amount decimal not null, enabled bool not null, usage_limit integer null, used_count integer not null, created_at datetime not null);
CREATE TABLE store_payment (id integer primary key autoincrement, order_id bigint unique not null references store_order(id), provider varchar(20) not null, provider_payment_id varchar(180) not null, amount decimal not null, status varchar(20) not null, created_at datetime not null);
CREATE TABLE store_prescription (id integer primary key autoincrement, customer_id bigint not null references auth_user(id), order_id bigint null references store_order(id), file varchar(100) not null, original_name varchar(255) not null, status varchar(20) not null, notes text not null, uploaded_at datetime not null, reviewed_at datetime null);
CREATE TABLE store_banner (id integer primary key autoincrement, title varchar(160) not null, subtitle varchar(240) not null, image varchar(100) null, link_url varchar(200) not null, featured bool not null, published bool not null, sort_order integer not null);
CREATE TABLE store_sitecontent (id integer primary key autoincrement, key varchar(40) unique not null, title varchar(160) not null, body text not null, published bool not null, updated_at datetime not null);
CREATE TABLE store_faq (id integer primary key autoincrement, question varchar(240) not null, answer text not null, published bool not null, sort_order integer not null);
